class Solution:
    def countOddLetters(self, n):
        words = ["zero","one","two","three","four","five","six","seven","eight","nine"]
        from collections import Counter
        c = Counter()
        for ch in str(n):
            c.update(words[int(ch)])
        return sum(1 for v in c.values() if v % 2 == 1)

