class Solution {
    public int countOddLetters(int n) {
        String[] w = {"zero","one","two","three","four","five","six","seven","eight","nine"};
        int[] cnt = new int[26];
        for (char d : String.valueOf(n).toCharArray())
            for (char ch : w[d - '0'].toCharArray()) cnt[ch - 'a']++;
        int ans = 0;
        for (int c : cnt) if (c % 2 == 1) ans++;
        return ans;
    }
}

