var countOddLetters = function(n) {
    const w = ["zero","one","two","three","four","five","six","seven","eight","nine"];
    const cnt = {};
    for (const d of String(n))
        for (const ch of w[+d]) cnt[ch] = (cnt[ch] || 0) + 1;
    return Object.values(cnt).filter(v => v % 2 === 1).length;
};
